import axios from "axios";

// ─────────────────────────────────────────────────────────────────────────────
// AUTO IP DETECTION
//
// Problem: When you open the app from ANOTHER device on the same WiFi,
// "localhost" in the browser means THAT device — not your PC running the backend.
//
// Solution: Detect which hostname the browser is currently using.
//   • If it's "localhost" or "127.0.0.1" → you're on your own PC → use localhost
//   • If it's anything else (e.g. 192.168.1.5) → you opened it from another device
//     → use THAT same IP but with port 8080 (where Spring Boot is running)
//
// This means: just open http://<your-pc-ip>:3000 on any device and everything
// connects automatically. No manual .env editing required.
// ─────────────────────────────────────────────────────────────────────────────

function getBackendURL() {
  // 1. If a manual override is set in .env, always use that
  if (process.env.REACT_APP_API_URL) {
    return process.env.REACT_APP_API_URL;
  }

  const host = window.location.hostname;

  // 2. Local machine — use localhost directly
  if (host === "localhost" || host === "127.0.0.1") {
    return "http://localhost:8080";
  }

  // 3. Another device opened the app via LAN IP (e.g. http://192.168.1.5:3000)
  // The backend is on the SAME machine that serves React, just port 8080
  return `http://${host}:8080`;
}

const BASE = getBackendURL();

// Show the resolved URL in dev console so you can confirm it's correct
if (process.env.NODE_ENV === "development") {
  console.log(`🔌 Crisp backend URL: ${BASE}`);
}

const api = axios.create({
  baseURL: BASE,
  timeout: 10000, // 10s timeout — shows a clear error instead of hanging forever
});

// Attach JWT to every request automatically
api.interceptors.request.use((config) => {
  const token = localStorage.getItem("crisp_token");
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

// Global response error handler — normalises all error shapes
api.interceptors.response.use(
  (res) => res,
  (err) => {
    if (!err.response) {
      // Network error — backend not running or wrong IP
      err.friendlyMessage =
        "Cannot reach the server. Make sure the backend is running on port 8080.";
    } else {
      const d = err.response.data;
      err.friendlyMessage =
        typeof d === "string"
          ? d
          : d?.error || d?.message || `Error ${err.response.status}`;
    }
    return Promise.reject(err);
  }
);

// ── Auth ──────────────────────────────────────────────────────────────────────
export const login    = (u, p)    => api.post("/api/auth/login",    { username: u, password: p });
export const register = (u, p, f) => api.post("/api/auth/register", { username: u, password: p, fullName: f });

// ── Rooms ─────────────────────────────────────────────────────────────────────
export const getUserRooms   = (u)    => api.get(`/api/rooms/user/${u}`);
export const createRoom     = (body) => api.post("/api/rooms/create", body);
export const getChatHistory = (id)   => api.get(`/api/rooms/${id}/history`);

// ── Users ─────────────────────────────────────────────────────────────────────
export const getAllUsers   = ()  => api.get("/api/users");
export const getUserStatus = (u) => api.get(`/api/users/${u}`);

export { BASE as BACKEND_URL };
export default api;
